// Models mirror the JSON bodies of gwt/.../shared/dto/*.java (Jackson property names).
export interface ManufacturerDto {
  id?: number | null;
  name: string;
  cars?: CarDto[];
}

export interface CarPropertiesDto {
  someString?: string;
  someNumber?: number;
  someDate?: string;
}

export interface CarDto {
  id?: number | null;
  model: string;
  manufacturer: ManufacturerDto | null;
  ratings?: RatingDto[];
  carProperties?: CarPropertiesDto;
}

export interface RatingDto {
  id?: number | null;
  rating: number | null;
  car: CarDto | null;
}

export interface ManufacturerRatingDto {
  manufacturer: string;
  rating: number;
}

/** Same rendering as RatingDto.toString() in the GWT app: "Manufacturer/Model". */
export function carLabel(car: CarDto | null): string {
  if (!car) {
    return '';
  }
  return (car.manufacturer ? car.manufacturer.name : '') + '/' + car.model;
}
EOF
