import { Component, OnInit, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { ManufacturerDto } from '../api';
import { MessageService } from '../widget/message/message.service';

@Component({
  selector: 'app-manufacturers',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="title">
      <h2>Manufacturers</h2>
      <button id="gwt-debug-create-manufacturer" (click)="create()">Create</button>
    </div>
    <table id="gwt-debug-manufacturers">
      <thead>
        <tr><th>Name</th><th></th><th></th></tr>
      </thead>
      <tbody>
        @for (m of manufacturers(); track $index) {
          <tr>
            <td>{{ m.name }}</td>
            <td><button (click)="edit(m)">Edit</button></td>
            <td><button (click)="remove(m)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>

    @if (editing(); as target) {
      <div id="gwt-debug-manufacturer-editor" class="popup">
        <div>
          <label>Name:</label>
          <input id="gwt-debug-manufacturer-input" type="text" [(ngModel)]="draftName" />
        </div>
        <div>
          <button id="gwt-debug-manufacturer-save" (click)="save(target)">Save</button>
          <button id="gwt-debug-manufacturer-close" (click)="close()">Close</button>
        </div>
      </div>
    }
  `,
})
export class ManufacturersComponent implements OnInit {
  private readonly http = inject(HttpClient);
  private readonly messages = inject(MessageService);

  readonly manufacturers = signal<ManufacturerDto[]>([]);
  /** null = popup closed; a ManufacturerDto with no id = create; otherwise edit. */
  readonly editing = signal<ManufacturerDto | null>(null);
  draftName = '';

  ngOnInit(): void {
    this.http.get<ManufacturerDto[]>('/api/manufacturers').subscribe({
      next: (list) => this.manufacturers.set(list),
      error: () => this.messages.error('Unable to load manufacturers'),
    });
  }

  create(): void {
    this.draftName = '';
    this.editing.set({ name: '' });
  }

  edit(m: ManufacturerDto): void {
    this.draftName = m.name;
    this.editing.set(m);
  }

  close(): void {
    this.editing.set(null);
  }

  save(target: ManufacturerDto): void {
    const body: ManufacturerDto = { ...target, name: this.draftName };
    this.http.post<ManufacturerDto>('/api/manufacturers', body).subscribe({
      next: (saved) => {
        this.manufacturers.update((list) => {
          const index = list.findIndex((m) => m.id != null && m.id === saved.id);
          if (index >= 0) {
            const copy = [...list];
            copy[index] = saved;
            return copy;
          }
          return [...list, saved];
        });
        this.messages.success('Manufacturer saved');
        this.editing.set(null);
      },
      error: () => this.messages.error('Unable to save the manufacturer'),
    });
  }

  remove(m: ManufacturerDto): void {
    if (!window.confirm('Are you sure you want to delete this manufacturer?')) {
      return;
    }
    this.http.delete<void>(`/api/manufacturers/${m.id}`).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((x) => x !== m)),
      error: () => this.messages.error('Unable to delete the manufacturer'),
    });
  }
}
