          <label>Car:</label>
          <select id="gwt-debug-ratingCar" [(ngModel)]="selectedCarId">
            @for (c of cars(); track c.id) {
              <option [ngValue]="c.id">{{ carName(c) }}</option>
            }
          </select>
        </div>
        <div>
          <label>Your rating:</label>
          <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="draftRating" />
        </div>
        <div>
          <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button id="gwt-debug-ratingClose" (click)="closeEditor()">Close</button>
        </div>
      </div>
    }
  `,
})
export class RatingsComponent implements OnInit {
  private readonly http = inject(HttpClient);
  private readonly messages = inject(MessageService);

  readonly ratings = signal<RatingDto[]>([]);
  readonly cars = signal<CarDto[]>([]);
  readonly editorOpen = signal(false);
  selectedCarId: number | null = null;
  draftRating: number | null = null;

  ngOnInit(): void {
    this.http.get<RatingDto[]>('/api/ratings').subscribe({
      next: (list) => this.ratings.set(list),
      error: () => this.messages.error('Unable to load ratings'),
    });
  }

  carName(car: CarDto | null): string {
    return carLabel(car);
  }

  openEditor(): void {
    this.draftRating = null;
    this.http.get<CarDto[]>('/api/cars', { params: { offset: 0, limit: -1 } }).subscribe({
      next: (cars) => {
        this.cars.set(cars);
        this.selectedCarId = cars.length > 0 && cars[0].id != null ? cars[0].id : null;
        this.editorOpen.set(true);
      },
      error: () => this.messages.error('Unable to load cars'),
    });
  }

  closeEditor(): void {
    this.editorOpen.set(false);
  }

  save(): void {
    const car = this.cars().find((c) => c.id === this.selectedCarId) ?? null;
    const body: RatingDto = { rating: this.draftRating, car };
    this.http.post<RatingDto>('/api/ratings', body).subscribe({
      next: (saved) => {
        this.ratings.update((list) => [...list, saved]);
        this.messages.success('Rating saved');
        this.editorOpen.set(false);
      },
      error: () => this.messages.error('Unable to save the rating'),
    });
  }

  remove(r: RatingDto): void {
    if (!window.confirm('Are you sure you want to delete this rating?')) {
      return;
    }
    this.http.delete<void>(`/api/ratings/${r.id}`).subscribe({
      next: () => this.ratings.update((list) => list.filter((x) => x !== r)),
      error: () => this.messages.error('Unable to delete the rating'),
    });
  }
}
