package com.gwtplatform.carstore.cucumber.harness;

import com.google.inject.AbstractModule;
import com.google.inject.Provides;
import com.gwtplatform.carstore.cucumber.application.widgets.HeaderWidgetPage;
import cucumber.api.java.After;
import cucumber.api.java.en.Given;
import cucumber.runtime.java.guice.ScenarioScoped;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import javax.inject.Inject;

/** Harness only (not part of the migrated app): provides WebDriver, the login/navigation steps and hooks. */
public class Harness extends AbstractModule {
    public static final String BASE_URL = System.getProperty("e2e.url", "http://localhost:8888/ng/");
    private static WebDriver driver;

    @Override
    protected void configure() {
        bind(Harness.class);
    }

    @Provides
    @ScenarioScoped
    WebDriver provideDriver() {
        if (driver == null) {
            ChromeOptions options = new ChromeOptions();
            options.setBinary("/usr/bin/chromium");
            options.addArguments("--headless=new", "--no-sandbox", "--disable-gpu", "--window-size=1280,1000");
            driver = new ChromeDriver(options);
            Runtime.getRuntime().addShutdownHook(new Thread(() -> driver.quit()));
        }
        return driver;
    }

    public static class Steps {
        private final WebDriver webDriver;
        private final HeaderWidgetPage header;

        @Inject
        Steps(WebDriver webDriver, HeaderWidgetPage header) {
            this.webDriver = webDriver;
            this.header = header;
        }

        @Given("^I'm logged in$")
        public void loggedIn() {
            // Login is out of scope: the REST API is not protected.
            webDriver.get(BASE_URL);
        }

        @Given("^I navigate to the (manufacturer|rating|report) page$")
        public void navigate(String token) {
            if (!webDriver.getCurrentUrl().startsWith(BASE_URL)) {
                webDriver.get(BASE_URL);
            }
            header.navigateTo(token);
        }
    }
}
EOF
